"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["77512"],{8248(e){e.exports=JSON.parse('{"id":"F506","slug":"research-pitch-risk-reward","name":"Equity Research Pitch: Target Price and Risk/Reward","subject":"Practical Skills & Capstone","section":"Putting It Together","topic":"Write an equity research pitch","level":"Intermediate","aliases":["write an equity research pitch","target price","bull base bear","upside downside ratio","implied multiple"],"formula":{"latex":"P_{target}=EPS\\\\times PE,\\\\quad E[P]=\\\\sum p_{s}P_{s},\\\\quad RR=\\\\frac{P_{bull}-P_{0}}{P_{0}-P_{bear}}","also":[],"text":"Base target price = forecast earnings per share x target price-to-earnings multiple; Expected value = sum of probability x price over bull, base and bear; Upside to expected value = expected price / current price - 1; Risk/reward = (bull price - current price) / (current price - bear price); Implied multiple at the current price = price / forecast EPS"},"symbols":[{"symbol":"EPS","meaning":"Forecast earnings per share","unit":"money"},{"symbol":"PE","meaning":"Multiple the market is expected to pay","unit":"number"},{"symbol":"p_s","meaning":"Probability of scenario s","unit":"percent"}],"when_to_use":"Use it to put a recommendation on a few clear numbers. State what you expect earnings to be, what multiple you think is fair, and what happens in good and bad cases. A pitch should say what would make it wrong. The probabilities are your judgment, so say why you chose them.","worked_example":{"problem":"A stock trades at 78. Forecast EPS is 5.20 and the fair multiple is 19. The bull price is 118, the bear price is 52, and the probabilities are 25% bull, 50% base and 25% bear.","inputs":{"e":5.2,"m":19,"p0":78,"pb":118,"pr":52,"wb":25,"wr":25},"steps":[{"label":"Base target price","working":"5.2 x 19","value":"98.80"},{"label":"Upside to the base target","working":"98.8 / 78-1","value":"26.7%"},{"label":"Probability-weighted value","working":"0.25 x 118+(1-0.25-0.25) x 98.8+0.25 x 52","value":"91.90"},{"label":"Upside to expected value","working":"91.9 / 78-1","value":"17.8%"},{"label":"Risk/reward ratio","working":"(118-78) / (78-52)","value":"1.54"},{"label":"Current multiple on forecast EPS","working":"78 / 5.2","value":"15.0"}],"answer":"The base target is 98.80, or 26.7% above the current price. The probability-weighted value is 91.90, an upside of 17.8%. Risk/reward is 1.54: for each 1 you could lose in the bear case you could gain that much in the bull case. At 78 the stock trades on 15.0 times forecast earnings."},"calculator":{"available":true,"inputs":[{"id":"e","label":"Forecast EPS","unit":"money","type":"number","default":5.2,"hint":""},{"id":"m","label":"Target multiple","unit":"","type":"number","default":19,"hint":""},{"id":"p0","label":"Current price","unit":"money","type":"number","default":78,"hint":""},{"id":"pb","label":"Bull price","unit":"money","type":"number","default":118,"hint":""},{"id":"pr","label":"Bear price","unit":"money","type":"number","default":52,"hint":""},{"id":"wb","label":"Probability of bull","unit":"%","type":"number","default":25,"hint":""},{"id":"wr","label":"Probability of bear","unit":"%","type":"number","default":25,"hint":""}],"checks":[{"expr":"wb+wr<=1 and p0>pr","message":"Probabilities must add up to no more than 100% and the current price must exceed the bear price."}],"steps":[{"id":"base","label":"Base target price","expr":"e*m","format":"money"},{"id":"up_b","label":"Upside to the base target","expr":"base/p0-1","format":"pct1"},{"id":"ev","label":"Probability-weighted value","expr":"wb*pb+(1-wb-wr)*base+wr*pr","format":"money"},{"id":"up","label":"Upside to expected value","expr":"ev/p0-1","format":"pct1"},{"id":"rr","label":"Risk/reward ratio","expr":"(pb-p0)/(p0-pr)","format":"num2"},{"id":"impl","label":"Current multiple on forecast EPS","expr":"p0/e","format":"num1"}],"results":["base","up","rr","impl"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"base":98.8,"up_b":0.2666666666666666,"ev":91.9,"up":0.17820512820512824,"rr":1.5384615384615385,"impl":15}},"finder":{"finds":"The numbers at the core of a stock recommendation","needs":"EPS forecast, target multiple, scenario prices and probabilities"},"related":[{"slug":"price-target-upside","name":"Price Target and Upside (Equity Research)"},{"slug":"expected-value","name":"Expected Value"},{"slug":"pe-earnings-yield","name":"P/E Ratio and Earnings Yield"}],"related_ids":["F280","F058","F271"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>P</mi><mrow><mi>t</mi><mi>a</mi><mi>r</mi><mi>g</mi><mi>e</mi><mi>t</mi></mrow></msub><mo>=</mo><mi>E</mi><mi>P</mi><mi>S</mi><mo>\xd7</mo><mi>P</mi><mi>E</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>E</mi><mo stretchy=\\"false\\">[</mo><mi>P</mi><mo stretchy=\\"false\\">]</mo><mo>=</mo><mo>\u2211</mo><msub><mi>p</mi><mi>s</mi></msub><msub><mi>P</mi><mi>s</mi></msub><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>R</mi><mi>R</mi><mo>=</mo><mfrac><mrow><msub><mi>P</mi><mrow><mi>b</mi><mi>u</mi><mi>l</mi><mi>l</mi></mrow></msub><mo>\u2212</mo><msub><mi>P</mi><mn>0</mn></msub></mrow><mrow><msub><mi>P</mi><mn>0</mn></msub><mo>\u2212</mo><msub><mi>P</mi><mrow><mi>b</mi><mi>e</mi><mi>a</mi><mi>r</mi></mrow></msub></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">P_{target}=EPS\\\\times PE,\\\\quad E[P]=\\\\sum p_{s}P_{s},\\\\quad RR=\\\\frac{P_{bull}-P_{0}}{P_{0}-P_{bear}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"equity-multiplier","name":"Equity Multiplier"},"next":{"slug":"equivalent-annual-annuity","name":"Equivalent Annual Annuity (EAA)"},"lesson":null,"total":522}')}}]);